def transform(grid):
    """Bridge aligned equal-color endpoints; mark the intervening background cells 2."""
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    background = max({v for row in grid for v in row}, key=lambda v: sum(row.count(v) for row in grid))
    changed = True
    while changed:
        changed = False
        for r in range(h):
            for a in range(w):
                if out[r][a] == background:
                    continue
                for b in range(a + 2, w):
                    if out[r][b] == out[r][a]:
                        for c in range(a + 1, b):
                            if out[r][c] == background:
                                out[r][c] = 2
                                changed = True
                        break
        for c in range(w):
            for a in range(h):
                if out[a][c] == background:
                    continue
                for b in range(a + 2, h):
                    if out[b][c] == out[a][c]:
                        for r in range(a + 1, b):
                            if out[r][c] == background:
                                out[r][c] = 2
                                changed = True
                        break
    return out
