def transform(grid):
    """Mark color-2 in vertical gaps between successive occurrences of the lone foreground color."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    foregrounds = [v for v in counts if v != background]
    if not foregrounds:
        return [row[:] for row in grid]
    foreground = max(foregrounds, key=counts.get)
    out = [row[:] for row in grid]
    for c in range(w):
        marks = [r for r in range(h) if grid[r][c] == foreground]
        for a, b in zip(marks, marks[1:]):
            for r in range(a + 1, b):
                if grid[r][c] == background:
                    out[r][c] = 2
    return out
