def transform(grid):
    """Fill vertical gaps in each foreground column and horizontal gaps on the outermost occupied rows."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    fg = max((v for v in counts if v != bg), key=lambda v: counts[v])
    out = [row[:] for row in grid]
    occupied_rows = [r for r in range(h) if any(v == fg for v in grid[r])]

    for c in range(w):
        marks = [r for r in range(h) if grid[r][c] == fg]
        for a, b in zip(marks, marks[1:]):
            for r in range(a + 1, b):
                if grid[r][c] == bg:
                    out[r][c] = 2

    if occupied_rows:
        for r in {occupied_rows[0], occupied_rows[-1]}:
            marks = [c for c in range(w) if grid[r][c] == fg]
            for a, b in zip(marks, marks[1:]):
                for c in range(a + 1, b):
                    if grid[r][c] == bg:
                        out[r][c] = 2
    return out
