def transform(grid):
    """Connect the nearest aligned separate foreground runs with 2-colored bridges."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    fg = max((v for v in counts if v != bg), key=lambda v: counts[v])
    out = [row[:] for row in grid]

    # Bridge one-cell vertical gaps separating consecutive foreground marks.
    for c in range(w):
        marks = [r for r in range(h) if grid[r][c] == fg]
        for a, b in zip(marks, marks[1:]):
            if b - a == 2 and grid[a + 1][c] == bg:
                out[a + 1][c] = 2

    # On each row, join isolated vertical strokes when a horizontal gap of
    # two cells lies between their foreground endpoints.
    for r in range(h):
        marks = [c for c in range(w) if grid[r][c] == fg]
        for a, b in zip(marks, marks[1:]):
            if b - a == 3 and all(grid[r][c] == bg for c in range(a + 1, b)):
                out[r][a + 1] = out[r][a + 2] = 2
    return out
