    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    fg = max((v for v in counts if v != bg), key=lambda v: counts[v])
    out = [row[:] for row in grid]
    # Fill vertical gaps between successive occurrences.
    for c in range(w):
        marks = [r for r in range(h) if grid[r][c] == fg]
        for a, b in zip(marks, marks[1:]):
            for r in range(a + 1, b):
                if grid[r][c] == bg:
                    out[r][c] = 2
    # Horizontal bridges from a vertical stroke endpoint to a neighboring
    # aligned foreground mark; do not bridge between two continuing strokes.
    for r in range(h):
        marks = [c for c in range(w) if grid[r][c] == fg]
        for a, b in zip(marks, marks[1:]):
            def endpoint(c):
                up = r > 0 and grid[r-1][c] == fg
                down = r+1 < h and grid[r+1][c] == fg
                return not (up and down)
            if endpoint(a) or endpoint(b):
                for c in range(a + 1, b):
                    if grid[r][c] == bg:
                        out[r][c] = 2
    return out
